-- 1. TIME TRACKING
-- =============================================================================
-- time_entries: PROVEN fields start/end/duration/description/billable/source/at/is_locked/approval_id/tid/user_id.
-- ASSUMED: soft delete, rate snapshot, denormalised list_id, hash partitioning.
-- PARTITION BY HASH (workspace_id) x 8: write-heavy, always read per workspace; unique keys contain workspace_id.
CREATE TABLE time_entries (
  id            uuid NOT NULL,                       -- client-generated
  workspace_id  uuid NOT NULL /* id -> access.workspaces */,
  task_id       uuid /* id -> tasks.tasks */,           -- ASSUMED nullable: entry without a task
  list_id       uuid /* id -> hierarchy.lists */,           -- ASSUMED denormalised at write time for list reports
  user_id       uuid NOT NULL /* id -> identity.users */,
  started_at    timestamptz NOT NULL,
  ended_at      timestamptz,                         -- NULL while the timer runs (PROVEN: ClickUp sends a negative duration)
  duration_ms   bigint,                              -- NULL while running; ASSUMED: never store negative
  description   text NOT NULL DEFAULT '',
  billable      boolean NOT NULL DEFAULT false,
  rate_cents    bigint,                              -- ASSUMED rate snapshot at stop time (billable_rates)
  rate_currency char(3),
  source        text NOT NULL DEFAULT 'timer'
                CHECK (source IN ('timer','manual','timesheet','automatic','import')),  -- PROVEN: clickup_automatic seen
  is_locked     boolean NOT NULL DEFAULT false,      -- PROVEN field; set once an approval exists
  approval_id   uuid,                                -- FK added below (timesheet_approvals)
  deleted_at    timestamptz,                         -- ASSUMED
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       integer NOT NULL DEFAULT 1,
  PRIMARY KEY (workspace_id, id),
  CHECK (ended_at IS NULL OR ended_at >= started_at),
  CHECK ((ended_at IS NULL) = (duration_ms IS NULL)),
  CHECK (duration_ms IS NULL OR duration_ms >= 0)
) PARTITION BY HASH (workspace_id);

SELECT support_hash_partitions('time_entries', 8);

-- one running timer per user per workspace (ASSUMED reading of GET time_entries/current). Serves 'current timer'.
CREATE UNIQUE INDEX time_entries_one_running ON time_entries (workspace_id, user_id)
  WHERE ended_at IS NULL AND deleted_at IS NULL;

-- 'timesheet for week' and 'my entries'.
CREATE INDEX time_entries_user_time ON time_entries (workspace_id, user_id, started_at DESC) WHERE deleted_at IS NULL;

-- 'time on this task' panel and rollups.
CREATE INDEX time_entries_task ON time_entries (workspace_id, task_id, started_at) WHERE deleted_at IS NULL AND task_id IS NOT NULL;

-- time reports by list / date range.
CREATE INDEX time_entries_list ON time_entries (workspace_id, list_id, started_at) WHERE deleted_at IS NULL;

-- billable report.
CREATE INDEX time_entries_billable ON time_entries (workspace_id, started_at) WHERE billable AND deleted_at IS NULL;

-- time-entry tag names are a workspace-level list in ClickUp (PROVEN: time_entries/tags); ours is its own table.
CREATE TABLE time_tags (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  name text NOT NULL,
  color text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1,
  UNIQUE (workspace_id, name)
);

CREATE TABLE time_entry_tag_links (
  workspace_id uuid NOT NULL,
  entry_id uuid NOT NULL,
  time_tag_id uuid NOT NULL REFERENCES time_tags(id) ON DELETE CASCADE,
  PRIMARY KEY (workspace_id, entry_id, time_tag_id),
  FOREIGN KEY (workspace_id, entry_id) REFERENCES time_entries(workspace_id, id) ON DELETE CASCADE
);

CREATE INDEX time_entry_tag_links_tag ON time_entry_tag_links (workspace_id, time_tag_id);

-- timesheet approvals: weekly timesheets are a view over entries (PROVEN); approval rows ASSUMED.
CREATE TABLE timesheet_approvals (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  user_id uuid NOT NULL /* id -> identity.users */,
  week_start date NOT NULL,                          -- first day of week per workspace week-start setting
  status text NOT NULL DEFAULT 'submitted'
         CHECK (status IN ('submitted','approved','rejected','reopened')),  -- 'Open'/'Not submitted' (PROVEN) = no row
  tracked_ms bigint,                                 -- ASSUMED snapshot at submit
  submitted_at timestamptz,
  reviewer_id uuid /* id -> identity.users */,
  reviewed_at timestamptz,
  review_note text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1,
  UNIQUE (workspace_id, user_id, week_start)
);

-- approvals screen: pending queue for reviewers.
CREATE INDEX timesheet_approvals_queue ON timesheet_approvals (workspace_id, status, week_start);

ALTER TABLE time_entries ADD CONSTRAINT time_entries_approval_fk
  FOREIGN KEY (approval_id) REFERENCES timesheet_approvals(id);

-- capacity: PROVEN shape (per weekday 0..6 for time estimate, points, tasks + weekly total) -> settings JSONB, never filtered.
CREATE TABLE user_capacity (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  user_id uuid NOT NULL /* id -> identity.users */,
  time_estimate jsonb NOT NULL DEFAULT '{"type":"weekly"}',
  points jsonb NOT NULL DEFAULT '{"type":"weekly"}',
  tasks jsonb NOT NULL DEFAULT '{"type":"weekly"}',
  skip_weekends boolean NOT NULL DEFAULT false,
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1,
  PRIMARY KEY (workspace_id, user_id)
);

-- 'timesheet for week': per-day totals in the viewer's timezone (ASSUMED; a stored view would hard-code UTC).
CREATE OR REPLACE FUNCTION timesheet_week(p_workspace uuid, p_user uuid, p_week_start date, p_tz text DEFAULT 'UTC')
RETURNS TABLE(day date, tracked_ms bigint, billable_ms bigint) LANGUAGE sql STABLE AS $$
  SELECT (e.started_at AT TIME ZONE p_tz)::date, sum(e.duration_ms)::bigint,
         coalesce(sum(e.duration_ms) FILTER (WHERE e.billable), 0)::bigint
  FROM time_entries e
  WHERE e.workspace_id = p_workspace AND e.user_id = p_user AND e.deleted_at IS NULL AND e.ended_at IS NOT NULL
    AND e.started_at >= (p_week_start::timestamp AT TIME ZONE p_tz)
    AND e.started_at <  ((p_week_start + 7)::timestamp AT TIME ZONE p_tz)
  GROUP BY 1 ORDER BY 1 $$;

