-- 8. AVAILABILITY and capacity  (FR-607, FR-608, T-07..T-09)
-- =============================================================================
CREATE TABLE work_schedules (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  user_id uuid NOT NULL /* id -> identity.users */,
  timezone text NOT NULL,
  weekly_minutes smallint[7] NOT NULL DEFAULT '{0,480,480,480,480,480,0}',   -- Sun..Sat
  holiday_calendar_id uuid,
  effective_from date NOT NULL DEFAULT current_date,
  updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1,
  PRIMARY KEY (workspace_id, user_id, effective_from)
);

CREATE TABLE holiday_calendars (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  name text NOT NULL, region text,
  updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1
);

CREATE TABLE holidays (
  calendar_id uuid NOT NULL REFERENCES holiday_calendars(id) ON DELETE CASCADE,
  day date NOT NULL, name text NOT NULL,
  PRIMARY KEY (calendar_id, day)
);

ALTER TABLE work_schedules ADD CONSTRAINT work_schedules_cal_fk FOREIGN KEY (holiday_calendar_id) REFERENCES holiday_calendars(id);

